// Get current date/time in New York
const nyTimeString = new Date().toLocaleString("en-US", {timeZone: "America/New_York"});
const nyTime = new Date(nyTimeString);

const day = nyTime.getDay(); // 0 = Sunday, 6 = Saturday
const hours = nyTime.getHours();
const minutes = nyTime.getMinutes();

// Convert current NY time to total minutes past midnight
const currentMinutes = (hours * 60) + minutes;
const marketOpenMinutes = (9 * 60) + 30; // 9:30 AM
const marketCloseMinutes = 16 * 60;      // 4:00 PM

// Check if it's a weekday and within regular trading hours
const isWeekday = day > 0 && day < 6;
const isTradingHours = currentMinutes >= marketOpenMinutes && currentMinutes < marketCloseMinutes;
const isOpen = isWeekday && isTradingHours;

return [{
  json: {
    exchange: "NYSE/NASDAQ",
    timezone: "America/New_York",
    isOpen: isOpen,
    nyTime: nyTimeString
  }
}];
